private fun symbol(name: String, pathData: String): ImageVector =
    ImageVector.Builder(
        name = name,
        defaultWidth = 24.dp,
        defaultHeight = 24.dp,
        viewportWidth = 960f,
        viewportHeight = 960f,
    ).apply {
        addGroup(translationY = 960f) {
            addPath(
                pathData = addPathNodes(pathData),
                // Icon() tints the result, so the fill colour itself is irrelevant.
                fill = SolidColor(Color.Black),
            )
        }
    }.build()
